/*
 * SlumsMS ticket s-maproute: routing into maps the server or the client cannot load.
 *
 * The scan behind the table walks 11921 portal moves in this WZ; 60 of them lead into 39 maps that Map.wz has no image
 * for (38) or that crash the v83 client (1: Ristonia Rampart Residences, the owner's crash on TEST 2026-10-31). Before
 * this class such a move loaded null and threw inside MapFactory/GenericPortal, or worse, put a character into a map
 * the client dies on.
 *
 * The table (src/main/resources/soloMapling/map-routing.tsv, generated by tools/data-align/map_routing.py) says where
 * each of those moves goes instead. One policy, applied at every way into a map:
 *   - Character.getWarpMap / changeMap / forceChangeMap (unscripted portals, script and NPC warps, `!warp`, GM,
 *     event instances: all of them end up in those methods),
 *   - Character.loadCharFromDB through MapManager.getMap (a character saved inside a blocked map),
 *   - MapManager.getMap (the net for the direct factory loads that bypass a character),
 *   - GCWorldGraph (the bots' world graph drops blocked targets, so bots never plan a route into one).
 *
 * Switch: -Dslums.maps.routing=false turns the whole thing off (default on, so TEST has it without a config edit);
 * -Dslums.maps.routing.table=<path> reads a table from disk instead of the jar.
 */
package server.maps;

import client.Character;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import soloMapling.qa.QaLog;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

import tools.PacketCreator;

public final class MapRouting {
    private static final Logger log = LogManager.getLogger(MapRouting.class);

    /** classpath resource, generated by tools/data-align/map_routing.py */
    public static final String TABLE = "/soloMapling/map-routing.tsv";
    private static final String TABLE_PROPERTY = "slums.maps.routing.table";
    private static final String ENABLED_PROPERTY = "slums.maps.routing";
    private static final long LOG_INTERVAL_MS = 3_600_000L;

    /** Said to the player whose move is rerouted. Short, no place claims, no game names. */
    private static final String MSG_REROUTED = "That way is closed right now, so you were taken back.";
    /** Said to the player whose move leads nowhere at all: they stay put. */
    private static final String MSG_STAY = "That way doesn't lead anywhere right now.";

    /** A resolved destination: the map, the door to arrive at there ("" = the map's default), and the table row. */
    public record Move(int map, String portal, String reason, boolean stay) {
    }

    /** One table row after loading: where the move lands, the door to arrive at there, and why (the generator rule). */
    public record Route(int map, String portal, String reason) {
    }

    private static final boolean ENABLED = Boolean.parseBoolean(System.getProperty(ENABLED_PROPERTY, "true"));
    /** blocked map id -> kind ("missing" or "client-crash") */
    private static final Set<Integer> BLOCKED = new HashSet<>();
    private static final Map<Integer, String> KIND = new HashMap<>();
    /** (from << 32 | target) -> source portal name -> route */
    private static final Map<Long, Map<String, Route>> BY_PORTAL = new HashMap<>();
    /** (from << 32 | target) -> route, for rows whose source portal is "*" */
    private static final Map<Long, Route> ANY_PORTAL = new HashMap<>();
    /** target -> route, for rows whose source map is "*" (a script warp with no known origin) */
    private static final Map<Integer, Route> FROM_ANYWHERE = new HashMap<>();
    /** blocked map -> the map a character already inside it, or a move of unknown origin, goes to */
    private static final Map<Integer, Route> FALLBACK = new HashMap<>();
    private static final Map<String, Long> LAST_LOGGED = new ConcurrentHashMap<>();

    private static volatile String source = "none";

    static {
        try {
            load();
        } catch (IOException | RuntimeException e) {
            log.error("map routing: cannot read {} ({}), every move that needs a route is refused instead", TABLE,
                    e.toString());
            BY_PORTAL.clear();
            ANY_PORTAL.clear();
            FROM_ANYWHERE.clear();
            FALLBACK.clear();
        }
    }

    private MapRouting() {
    }

    private static long key(int from, int target) {
        return ((long) from << 32) | (target & 0xFFFFFFFFL);
    }

    private static void load() throws IOException {
        String override = System.getProperty(TABLE_PROPERTY);
        try (BufferedReader r = new BufferedReader(new InputStreamReader(open(override), StandardCharsets.UTF_8))) {
            boolean blockedSection = false;
            String line;
            int routes = 0;
            int blocked = 0;
            while ((line = r.readLine()) != null) {
                if (line.startsWith("# routes:")) {
                    blockedSection = false;
                    continue;
                }
                if (line.startsWith("# blocked_maps:")) {
                    blockedSection = true;
                    continue;
                }
                if (line.isBlank() || line.startsWith("#")) {
                    continue;
                }
                int hash = line.indexOf(" # manual");
                if (hash >= 0) {
                    line = line.substring(0, hash);
                }
                String[] c = line.split("\t");
                try {
                    if (blockedSection) {
                        if (c.length < 4) {
                            continue;
                        }
                        int map = Integer.parseInt(c[0].trim());
                        String kind = c[1].trim();
                        BLOCKED.add(map);
                        KIND.put(map, kind);
                        FALLBACK.put(map, new Route(Integer.parseInt(c[3].trim()), "", "blocked " + kind));
                        blocked++;
                    } else {
                        if (c.length < 6) {
                            continue;
                        }
                        int from = c[0].trim().equals("*") ? 0 : Integer.parseInt(c[0].trim());
                        String portal = c[1].trim();
                        int target = Integer.parseInt(c[2].trim());
                        Route route = new Route(Integer.parseInt(c[3].trim()), c[4].trim(), c[5].trim());
                        if (from == 0) {
                            FROM_ANYWHERE.put(target, route);
                        } else if (portal.equals("*")) {
                            ANY_PORTAL.put(key(from, target), route);
                        } else {
                            BY_PORTAL.computeIfAbsent(key(from, target), k -> new HashMap<>()).put(portal, route);
                        }
                        routes++;
                    }
                } catch (NumberFormatException e) {
                    log.warn("map routing: skipping unreadable table line '{}'", line);
                }
            }
            source = override == null ? "jar:" + TABLE : override;
            log.info("map routing: {} routes, {} blocked maps from {}", routes, blocked, source);
        }
    }

    private static InputStream open(String override) throws IOException {
        if (override != null) {
            return Files.newInputStream(Path.of(override));
        }
        InputStream in = MapRouting.class.getResourceAsStream(TABLE);
        if (in == null) {
            throw new IOException(TABLE + " is not in the jar");
        }
        return in;
    }

    public static boolean enabled() {
        return ENABLED;
    }

    public static boolean blocked(int map) {
        return ENABLED && BLOCKED.contains(map);
    }

    public static String kind(int map) {
        String k = KIND.get(map);
        return k == null ? "unknown" : k;
    }

    /**
     * The map a move of unknown origin (a character saved inside a blocked map, a direct factory load) goes to, or -1
     * when the map is fine. Never returns a blocked map.
     */
    public static int fallback(int map) {
        if (!ENABLED) {
            return -1;
        }
        Route route = FROM_ANYWHERE.get(map);
        if (route == null) {
            route = FALLBACK.get(map);
        }
        return route == null ? -1 : route.map();
    }

    /** The route a (from map, portal, target) move takes, or null when the move is fine as it is. */
    public static Route route(int from, String portal, int target) {
        if (!ENABLED) {
            return null;
        }
        Map<String, Route> byPortal = BY_PORTAL.get(key(from, target));
        if (byPortal != null && portal != null) {
            Route r = byPortal.get(portal);
            if (r != null) {
                return r;
            }
        }
        Route r = ANY_PORTAL.get(key(from, target));
        if (r != null) {
            return r;
        }
        r = FROM_ANYWHERE.get(target);
        if (r != null) {
            return r;
        }
        if (BLOCKED.contains(target)) {
            return FALLBACK.get(target);
        }
        return null;
    }

    /**
     * Where a move from chr's current map through portalName into targetMap really goes, or null when the move is
     * fine as it is. A blocked target is rerouted, a character is told so once per move, and a route that lands back
     * on the map they are standing in is reported as a stay so no warp packet is sent.
     */
    public static Move move(Character chr, int targetMap, String portalName) {
        if (!ENABLED) {
            return null;
        }
        int from = chr.getMap() == null ? 0 : chr.getMapId();
        Route route = route(from, portalName, targetMap);
        if (route == null) {
            return null;
        }
        boolean stay = route.map() == from;
        note(chr, from, portalName, targetMap, route);
        if (stay) {
            chr.dropMessage(5, MSG_STAY);
            chr.sendPacket(PacketCreator.enableActions());
        } else {
            chr.dropMessage(5, MSG_REROUTED);
        }
        return new Move(route.map(), route.portal(), route.reason(), stay);
    }

    private static void note(Character chr, int from, String portalName, int targetMap, Route route) {
        if (!QaLog.every("maprouting:" + targetMap, LOG_INTERVAL_MS)) {
            log.debug("map routing: chr {} {}:{}/{} -> {} ({})", chr.getName(), from, portalName, targetMap,
                    route.map(), route.reason());
            return;
        }
        String line = "chr " + chr.getName() + " " + from + (portalName == null ? "" : ":" + portalName) + " -> "
                + targetMap + " rerouted to " + route.map() + " (" + route.reason() + ")";
        log.info("map routing: {}", line);
        QaLog.map(QaLog.Topic.MAP_CHANGE, targetMap, "MAPROUTE " + line);
    }

    /** Table rows loaded, for tests and the QA suite. */
    public static int routeCount() {
        int n = FROM_ANYWHERE.size();
        for (Map<String, Route> m : BY_PORTAL.values()) {
            n += m.size();
        }
        return n + ANY_PORTAL.size();
    }

    public static int blockedCount() {
        return BLOCKED.size();
    }

    public static Set<Integer> blockedMaps() {
        return Collections.unmodifiableSet(BLOCKED);
    }

    /** The table this instance read, for tests and the QA suite. */
    public static String source() {
        return source;
    }
}
